llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Ipratropium, a quaternary ammonium tropane ester with the same tropic acid side chain as the query, had an absolute oral bioavailability of only 3.3% (range 0.9-6.1%) in healthy volunteers, directly supporting a low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tiotropium, which shares the epoxide-bridged quaternary ammonium tropane scaffold of the query, had an absolute oral bioavailability of only 2-3% in healthy humans, strongly supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "The low oral bioavailability of the close analogue ipratropium is partly attributed to active secretion by the intestinal mucosa, a mechanism consistent with the quaternary ammonium structure of the query and supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "One ipratropium study reported about 32% oral absorption by AUC comparison, which is above the 20% threshold and contradicts the majority of low-F estimates; however, it is an outlier against multiple consistent 2-3% measurements.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an epoxide-bridged quaternary ammonium tropane ester (oxitropium-like). The closest analogue ipratropium has absolute oral bioavailability of about 2-3% in multiple human studies, and tiotropium, which shares the epoxide-bridged quaternary tropane scaffold, also has F of 2-3%. Quaternary ammonium charge and active intestinal secretion limit absorption; the single 32% ipratropium AUC estimate is an outlier. Therefore F is predicted below 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule was retrieved.",
    "One ipratropium AUC-based estimate (~32%) conflicts with multiple renal-excretion-based estimates (~2-3%); the reason for the discrepancy is not resolved.",
    "No mechanistic data on intestinal permeability or efflux for the exact query were provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

